# Generated by Cursor (plan: PascalCase accept 6+ letters, each segment 3+)
"""Scan for PascalCase tokens 6+ letters with each segment 3+ letters; accept (identity)."""

import re

# At least two segments: [A-Z][a-z]{2,}(?:[A-Z][a-z]{2,})+ -> 6+ letters
PASCAL_ACCEPT_RE = re.compile(r"\b([A-Z][a-z]{2,}(?:[A-Z][a-z]{2,})+)\b")


def scan_turn_pascal_case_accept(
    text: str,
    path_str: str = "",
) -> list[tuple[str, int, str, str]]:
    """Emit (pascal_case_accept, start_index, span, path_str) for each match."""
    result: list[tuple[str, int, str, str]] = []
    for m in PASCAL_ACCEPT_RE.finditer(text):
        result.append(("pascal_case_accept", m.start(), m.group(1), path_str))
    return result
